// Processa cada item do array de entrada
return $input.all().map(item => {
  // Cria array para armazenar as 6 imagens (sempre)
  const imagens = [];

  // Itera sobre as 6 imagens obrigatórias
  for (let i = 1; i <= 6; i++) {
    const imagemUrl = item.json[`imagem${i}`] || '';
    const imagemStatus = item.json[`stat_imagem${i}`] || 'rejeitada';

    // Sempre adiciona, mesmo se vazia
    imagens.push({
      url: imagemUrl,
      status: imagemStatus
    });
  }

  // Retorna sempre com 6 imagens
  return {
    json: {
      imagens: imagens
    }
  };
});

// Processa cada item do array de entrada
return $input.all().map(item => {
  // Cria array para armazenar as imagens
  const imagens = [];

  // Itera enquanto encontrar imagens (não limita a quantidade)
  let i = 1;
  while (item.json[`imagem${i}_url`]) {
    const imagemUrl = item.json[`imagem${i}_url`];

    // Adiciona a URL no array se existir
    if (imagemUrl) {
      imagens.push(imagemUrl);
    }

    i++;
  }

  // Retorna o array de URLs
  return {
    json: {
      imagens: imagens
    }
  };
});

