// === Parâmetros ===
const THRESHOLD = 50;           // mínimo para aprovar
const MAX_ITENS = 30;           // máximo a retornar
const DECAY_HALF_LIFE_H = 48;   // meia-vida da recência (horas)
const DEDUPE_SIMILARITY = 0.85; // similaridade p/ dedupe (0..1)
const KEEP_SCORE_IN_OUTPUT = false; // true só p/ debug

// === Dicionários de relevância (tema tributário focado em empresas) ===
const KW = {
  forte: [
    // Básicos
    'tributo','tributos','tributário','tributária','tributárias','tributários',
    'imposto','impostos',

    // Impostos específicos (PJ)
    'icms','ipi','iss','irpj','csll','pis','cofins','iof','cide',

    // Reforma e mudanças
    'reforma tributária','sistema tributário','código tributário','ctn',

    // Fisco e fiscalização
    'fisco','arrecadação','fiscalização','autuação','execução fiscal',
    'notificação fiscal','cobrança tributária',

    // Planejamento e elisão
    'planejamento tributário','elisão fiscal','evasão fiscal','sonegação',

    // Incentivos e créditos
    'incentivo fiscal','incentivos fiscais','benefício fiscal','benefícios fiscais',
    'crédito tributário','compensação tributária','recuperação de crédito',

    // Órgãos e julgamentos
    'carf','stf','stj','receita federal','sefaz','pgfn',

    // Regimes e enquadramentos
    'simples nacional','lucro presumido','lucro real','lucro arbitrado',

    // Obrigações acessórias
    'sped','efd','ecf','dctf','dirf','perdcomp','nf-e','nota fiscal',
    'obrigações acessórias','bloco k'
  ],
  medio: [
    'contabilidade','contador','auditoria','compliance',
    'fraude fiscal','due diligence','jurisprudência','acórdão',
    'consulta tributária','instrução normativa','solução de consulta'
  ],
  fracos: [
    'jogos','game','celebridade','famoso','esporte','entretenimento',
    'show','cantor','cantora','filme','série','bbb','futebol',
    'meme','tiktok','gadget','smartphone'
  ],
  brasil: [
    'brasil','receita federal','carf','stf','stj',
    'sefaz','pgfn','procuradoria da fazenda nacional',
    'governo federal','congresso','câmara','senado'
  ],
  contextoEco: [
    'tributação','carga tributária empresarial','arrecadação','orçamento',
    'déficit fiscal','responsabilidade fiscal','economia','pib',
    'reforma','política fiscal','isenção','renúncia fiscal',
    'impacto tributário nos negócios','regime tributário empresas'
  ],
  pf: [ // lista para penalizar notícias de PF
    'irpf','iptu','ipva','pessoa física',
    'imposto de renda pessoa física','cpf','mei'
  ]
};

// === Funções auxiliares ===
const norm = (s='') =>
  String(s).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/https?:\/\/\S+/g,' ')
    .replace(/[^\p{L}\p{N}\s]/gu,' ')
    .replace(/\s+/g,' ')
    .trim();

const tokens = s => new Set(norm(s).split(' ').filter(t => t.length > 2));

const tokenSimilarity = (a,b) => {
  const A = tokens(a), B = tokens(b);
  const inter = [...A].filter(t => B.has(t)).length;
  return inter / (Math.max(A.size, B.size) || 1);
};

const hasAny = (text, list) => {
  const t = norm(text);
  return list.some(k => t.includes(norm(k)));
};

const hoursSince = (d) => {
  if (!d) return 1e9;
  const ts = new Date(d).getTime();
  return isNaN(ts) ? 1e9 : (Date.now() - ts) / 36e5;
};

const recencyMultiplier = (h) => {
  const lambda = Math.log(2) / DECAY_HALF_LIFE_H;
  return Math.exp(-lambda * h);
};

const scoreItem = (j) => {
  const title = j.title || '';
  const body = j['content:encoded'] || j.content || '';
  const snippet = j.contentSnippet || '';
  const cats = Array.isArray(j.categories)
    ? j.categories.map(c => typeof c === 'string' ? c : JSON.stringify(c)).join(' ')
    : (typeof j.categories === 'string' ? j.categories : '');
  const text = `${title} ${snippet} ${body} ${cats}`;

  let score = 0;
  const forte = hasAny(text, KW.forte);
  const contexto = hasAny(text, KW.contextoEco);

  if (forte) score += 40;
  if (hasAny(text, KW.medio)) score += 20;
  if (hasAny(text, KW.brasil)) score += 10;
  if (hasAny(text, KW.fracos)) score -= 50;
  if (hasAny(text, KW.pf)) score -= 40; // penaliza PF

  if (forte && contexto) score += 30;

  const hasNumber = /\b\d+([.,]\d+)?\b/.test(text);
  const hasPercent = /%\b/.test(text);
  if (contexto && hasPercent) score += 15;
  else if (contexto && hasNumber) score += 5;

  score *= recencyMultiplier(hoursSince(j.isoDate || j.pubDate));
  return Math.max(0, Math.min(100, Math.round(score)));
};

// === Pipeline ===
const seenTitles = [];
const scoredItems = [];

for (const item of items) {
  const j = { ...item.json };
  // 🚀 REGRA PRIORITÁRIA: se for do blog BMS, aprova direto
  const isBMS = (j.link || '').includes('bmsprojetos.com');

  if (isBMS) {
    seenTitles.push(j.title || '');
    scoredItems.push({ json: j, _score: 999 }); // score alto só pra ordenar no topo
    continue;
  }

  const s = scoreItem(j);

  let dup = false;
  for (const prevTitle of seenTitles) {
    if (tokenSimilarity(prevTitle, j.title || '') >= DEDUPE_SIMILARITY) {
      dup = true; break;
    }
  }
  if (dup) continue;

  if (s >= THRESHOLD) {
    seenTitles.push(j.title || '');
    if (KEEP_SCORE_IN_OUTPUT) j._score = s;
    scoredItems.push({ json: j, _score: s });
  }
}

scoredItems.sort((a,b) => b._score - a._score);
return scoredItems.slice(0, MAX_ITENS).map(i => ({ json: i.json }));

const items = $input.all();

return items.map(item => {
  const contexto = item.json.contexto || `
titulo da noticia: ${item.json.title}
link noticia: ${item.json.link}
resumo noticia: ${item.json.contentSnippet}
`;

  // Extrai link do contexto (caso exista nesse formato)
  const match = contexto.match(/link noticia:\s*(https?:\/\/\S+)/i);
  const linkExtraido = match ? match[1] : (item.json.link || null);

  return {
    json: {
      contexto: contexto.trim(),
      link_noticia: linkExtraido,
      status: "aprovada",
      nota: 10,
      justificativa: `Conteúdo aprovado por prioridade de fonte.`
    }
  };
});

const items = $('Info dos posts agendados').all();

const ideiasAnteriores = items
  .filter(item => item.json.titulo)
  .map(item => ({ titulo: item.json.titulo }));

const noticias = $('Escolhe a notícia por palavras chave ou origem (blog BMS)').all();

// pega config dinâmica (do nó de dados do cliente)
const configNode = $('Pega dados fixos do cliente').first();
let regrasFonte = [];

try {
  let raw = configNode.json.prioridade_fonte;

  if (raw) {
    // força aspas no campo link se não tiver
    raw = raw.replace(/"link":\s*([^",}\n]+)/g, '"link":"$1"');

    // transforma em array
    const parsed = JSON.parse(`[${raw}]`);

    regrasFonte = parsed;
  }
} catch (e) {
  console.log('Erro ao parsear prioridade_fonte:', e);
  regrasFonte = [];
}

return noticias.map(item => {
  const link = item.json.link || '';

  // calcula prioridade dinamicamente
  let prioridade = 0;
  let regraFonte = null;

  for (const regra of regrasFonte) {
    if (link.includes(regra.link)) {
      prioridade = regra.prioridade_fonte;
      regraFonte = regra.link;
      break; // pega a primeira que bater
    }
  }

  return {
    json: {
      title: item.json.title,
      link: link,
      contentSnippet: item.json.contentSnippet,
      isoDate: item.json.isoDate,
      total_ideias_anteriores: ideiasAnteriores.length,
      ideias_completas: ideiasAnteriores,

      // dinâmico agora
      regra_fonte: regraFonte,
      prioridade_fonte: prioridade
    }
  };
});

